-- Phase 2 foundation. Apply to a fresh Supabase project; no browser service key.
create extension if not exists pgcrypto;
create table public.profiles(id uuid primary key references auth.users on delete cascade, display_name text not null default '', created_at timestamptz not null default now());
create table public.babies(id uuid primary key default gen_random_uuid(), owner_id uuid not null references auth.users, name text not null check(length(name) between 1 and 80), date_of_birth date not null, timezone text not null default 'UTC', birth_weight_grams integer check(birth_weight_grams>0), picture_path text, feeding_preferences text, created_at timestamptz not null default now());
create table public.baby_caregivers(baby_id uuid references public.babies on delete cascade, user_id uuid references auth.users on delete cascade, role text not null default 'caregiver' check(role in ('owner','caregiver')), created_at timestamptz not null default now(), primary key(baby_id,user_id));
create function public.can_access_baby(baby uuid) returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.babies b where b.id=baby and b.owner_id=auth.uid()) or exists(select 1 from public.baby_caregivers c where c.baby_id=baby and c.user_id=auth.uid()); $$;
create function public.owns_baby(baby uuid) returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.babies b where b.id=baby and b.owner_id=auth.uid()); $$;
revoke all on function public.can_access_baby(uuid),public.owns_baby(uuid) from public;
grant execute on function public.can_access_baby(uuid),public.owns_baby(uuid) to authenticated;
create table public.feeding_sessions(id uuid primary key default gen_random_uuid(),baby_id uuid not null references public.babies on delete cascade,caregiver_id uuid not null references auth.users,started_at timestamptz not null,ended_at timestamptz,notes text check(length(notes)<=1000),revision bigint not null default 1,updated_at timestamptz not null default now(),deleted_at timestamptz,check(ended_at is null or ended_at>=started_at));
create unique index one_active_feed_per_baby on public.feeding_sessions(baby_id) where ended_at is null and deleted_at is null;
create table public.feeding_segments(id uuid primary key default gen_random_uuid(),session_id uuid not null references public.feeding_sessions on delete cascade,side text not null check(side in ('left','right')),started_at timestamptz not null,ended_at timestamptz,check(ended_at is null or ended_at>=started_at));
create unique index one_active_segment_per_session on public.feeding_segments(session_id) where ended_at is null;
create table public.diaper_events(id uuid primary key default gen_random_uuid(),baby_id uuid not null references public.babies on delete cascade,caregiver_id uuid not null references auth.users,occurred_at timestamptz not null,type text not null check(type in ('wet','dirty','both')),color text,consistency text,notes text check(length(notes)<=1000),revision bigint not null default 1,updated_at timestamptz not null default now(),deleted_at timestamptz);
create table public.reminder_preferences(id uuid primary key default gen_random_uuid(),baby_id uuid not null references public.babies on delete cascade,user_id uuid not null references auth.users on delete cascade,feeding_enabled boolean not null default false,diaper_enabled boolean not null default false,feeding_minutes integer not null default 180 check(feeding_minutes>=15),diaper_minutes integer not null default 180 check(diaper_minutes>=15),unique(baby_id,user_id));
create index caregivers_user_idx on public.baby_caregivers(user_id);
create index feeds_baby_time_idx on public.feeding_sessions(baby_id,started_at desc);
create index segments_session_idx on public.feeding_segments(session_id,started_at);
create index diapers_baby_time_idx on public.diaper_events(baby_id,occurred_at desc);
alter table public.profiles enable row level security;
alter table public.babies enable row level security;
alter table public.baby_caregivers enable row level security;
alter table public.feeding_sessions enable row level security;
alter table public.feeding_segments enable row level security;
alter table public.diaper_events enable row level security;
alter table public.reminder_preferences enable row level security;
create policy profile_self on public.profiles for all to authenticated using(id=auth.uid()) with check(id=auth.uid());
create policy baby_read on public.babies for select to authenticated using(public.can_access_baby(id));
create policy baby_create on public.babies for insert to authenticated with check(owner_id=auth.uid());
create policy baby_update on public.babies for update to authenticated using(public.owns_baby(id)) with check(owner_id=auth.uid());
create policy baby_delete on public.babies for delete to authenticated using(public.owns_baby(id));
create policy caregivers_read on public.baby_caregivers for select to authenticated using(public.can_access_baby(baby_id));
create policy caregivers_manage on public.baby_caregivers for all to authenticated using(public.owns_baby(baby_id)) with check(public.owns_baby(baby_id));
create policy feeds_read on public.feeding_sessions for select to authenticated using(public.can_access_baby(baby_id));
create policy feeds_create on public.feeding_sessions for insert to authenticated with check(public.can_access_baby(baby_id) and caregiver_id=auth.uid());
create policy feeds_edit on public.feeding_sessions for update to authenticated using(public.can_access_baby(baby_id)) with check(public.can_access_baby(baby_id));
create policy feeds_delete on public.feeding_sessions for delete to authenticated using(public.can_access_baby(baby_id));
create policy segments_access on public.feeding_segments for all to authenticated using(exists(select 1 from public.feeding_sessions s where s.id=session_id and public.can_access_baby(s.baby_id))) with check(exists(select 1 from public.feeding_sessions s where s.id=session_id and public.can_access_baby(s.baby_id)));
create policy diapers_read on public.diaper_events for select to authenticated using(public.can_access_baby(baby_id));
create policy diapers_create on public.diaper_events for insert to authenticated with check(public.can_access_baby(baby_id) and caregiver_id=auth.uid());
create policy diapers_edit on public.diaper_events for update to authenticated using(public.can_access_baby(baby_id)) with check(public.can_access_baby(baby_id));
create policy diapers_delete on public.diaper_events for delete to authenticated using(public.can_access_baby(baby_id));
create policy reminders_self on public.reminder_preferences for all to authenticated using(user_id=auth.uid() and public.can_access_baby(baby_id)) with check(user_id=auth.uid() and public.can_access_baby(baby_id));
-- Preserve tenant and attribution fields on edits. Future sync uses revision compare-and-swap.
create function public.guard_event_update() returns trigger language plpgsql set search_path='' as $$ begin if new.baby_id<>old.baby_id or new.caregiver_id<>old.caregiver_id then raise exception 'Baby and original caregiver are immutable'; end if; if new.revision<>old.revision then raise exception 'Revision is server managed'; end if; new.revision=old.revision+1;new.updated_at=now();return new;end; $$;
create trigger feed_revision before update on public.feeding_sessions for each row execute function public.guard_event_update();
create trigger diaper_revision before update on public.diaper_events for each row execute function public.guard_event_update();
alter publication supabase_realtime add table public.feeding_sessions,public.feeding_segments,public.diaper_events;
